  e=NS(api=NS(now_ms=lambda:ms('2026-11-17T02:00:00')),root='/tmp/offline/runtime')
  with self.assertRaisesRegex(BotError,'진입 시간 종료'):t.validate_entry(e,{'trend130':True,'action':'LONG','leverage':5},1)
