import ast,hashlib,json
from pathlib import Path
D=Path(__file__).resolve().parents[1];HOST=D/'phone_v141'
s=(D/'phone_1_4_0_setup.py').read_text()
assert hashlib.sha256(s.encode()).hexdigest()=='67db02a4f3ff664c8934f99fa7cf49b32457ae167fb79ce9b3d59cf3354d1af3'
tree=ast.parse(s);v={n.targets[0].id:ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign)}
pins=v['PINNED_BY_HOST'];pins['host-v37']={n:hashlib.sha256(x.encode()).hexdigest() for n,x in v['PAYLOAD'].items()}
for p in HOST.iterdir():
 if not p.is_file():continue
 x=p.read_text()
 if p.suffix=='.py':x=x.replace('1.4.0','1.4.1').replace('phone_mobile140_previous.json','phone_mobile141_previous.json')
 if p.name=='phone_service.py':
  x=x.replace("VERSION = 'phone-service-37'","VERSION = 'phone-service-38'").replace("MARKER = '# OKX phone service v37 managed boot hook'","MARKER = '# OKX phone service v38 managed boot hook'")
  if "LEGACY_MARKERS = ('# OKX phone service v37 managed boot hook'" not in x:x=x.replace('LEGACY_MARKERS = (',"LEGACY_MARKERS = ('# OKX phone service v37 managed boot hook', ")
 if p.name=='phone_update.py':x=x.replace('CURRENT = 37','CURRENT = 38')
 if p.name=='phone_button_upgrade.py':x=x.replace("'host-v36')","'host-v36', 'host-v37')")
 p.write_text(x)
(HOST/'phone_button_old_sources.json').write_text(json.dumps(pins,ensure_ascii=False,indent=2)+'\n')
payload={p.name:p.read_text() for p in sorted(HOST.iterdir()) if p.is_file()}
assert payload['phone_sources.json']==v['PAYLOAD']['phone_sources.json']
lines=s.splitlines(keepends=True)
for n in reversed(tree.body):
 if isinstance(n,ast.Assign):
  k=n.targets[0].id
  if k in v:lines[n.lineno-1:n.end_lineno]=[k+' = '+repr({'PINNED_BY_HOST':pins,'HOST_NEW':'host-v38','PAYLOAD':payload}[k])+'\n']
out=''.join(lines);tree=ast.parse(out);n=next(n for n in tree.body if isinstance(n,ast.Assign) and n.targets[0].id=='PAYLOAD');lines=out.splitlines(keepends=True)
tail=''.join(lines[n.end_lineno:]).replace('host-v37','host-v38').replace('1.4.0','1.4.1').replace("for host in ('host-v36'","for host in ('host-v37','host-v36'")
out=''.join(lines[:n.end_lineno])+tail
out=out.replace('Verified phone host-v37: mobile computation, candidate and quote coordination.','Verified phone host-v38: candidate quote priority, prewarm and expiry diagnostics.')
(D/'phone_1_4_1_setup.py').write_text(out)
meta=dict(bytes=len(out.encode()),chars=len(out),sha256=hashlib.sha256(out.encode()).hexdigest(),host='host-v38',version='1.4.1',files={n:hashlib.sha256(x.encode()).hexdigest() for n,x in payload.items()})
(Path(__file__).parent/'release.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in meta.items() if k!='files'}))
